// ?onDie@UpgradeDie@@UAEXPBVDamageInfo@@@Z
// partial score=0.9505 date=2026-10-02
// cl: /DNDEBUG /MD /EHsc
// UpgradeDie::onDie at retail 0x00256240 (101 B): slot 0 of the
// DieModuleInterface table 0x010B3444, which UpgradeDie's registered
// constructor 0x002560E0 stores at +0x10. The only route is ILT 0x0003CD35,
// whose VA appears once in the image. Zero Hour's DieModuleInterface declares
// one virtual, onDie(const DamageInfo *).
// Evidence: targets/game/reverse/identity_evidence/diemodule-slot0-ondie.md
//
// The body is Zero Hour's UpgradeDie::onDie: if the die mux (module data +0x8)
// applies, find the producer (Object +0x78) and, if it has the module data's
// upgrade (AsciiString at +0x34), remove it. `this` is the DieModuleInterface
// sub-object: module data at this-0xC, Object at this-8.

typedef bool Bool;
typedef int ObjectID;

class AsciiString;
class UpgradeTemplate;
class DamageInfo;

class Object
{
public:
	Bool hasUpgrade(const UpgradeTemplate *upgrade) const;
	void removeUpgrade(const UpgradeTemplate *upgrade);
	ObjectID getProducerID() const { return m_producerID; }

	char m_lead[0x78];
	ObjectID m_producerID;		// +0x78
};

class DieMuxData
{
public:
	Bool isDieApplicable(const Object *obj, const DamageInfo *damageInfo) const;
};

struct UpgradeDieModuleData
{
	char m_lead[8];
	DieMuxData m_dieMuxData;	// +0x08
	char m_gap[0x34 - 9];
	char m_upgradeName[4];		// +0x34, an AsciiString
};

class GameLogic
{
public:
	Object *findObjectByID(ObjectID id);
};

class UpgradeCenter
{
public:
	const UpgradeTemplate *findUpgrade(const AsciiString &name) const;
};

extern GameLogic *TheGameLogic;
extern UpgradeCenter *TheUpgradeCenter;

class UpgradeDie
{
public:
	virtual void onDie(const DamageInfo *damageInfo);

	const UpgradeDieModuleData *getUpgradeDieModuleData() const
	{
		return *reinterpret_cast<UpgradeDieModuleData *const *>(reinterpret_cast<const char *>(this) - 0xc);
	}
	Bool isDieApplicable(const DamageInfo *damageInfo) const
	{
		return getUpgradeDieModuleData()->m_dieMuxData.isDieApplicable(getObject(), damageInfo);
	}
	Object *getObject() const
	{
		return *reinterpret_cast<Object *const *>(reinterpret_cast<const char *>(this) - 8);
	}
};

void UpgradeDie::onDie(const DamageInfo *damageInfo)
{
	if (!isDieApplicable(damageInfo))
		return;

	Object *producer = TheGameLogic->findObjectByID(getObject()->getProducerID());
	if (producer)
	{
		const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgrade(
			*reinterpret_cast<const AsciiString *>(getUpgradeDieModuleData()->m_upgradeName));
		if (upgrade)
		{
			if (producer->hasUpgrade(upgrade))
				producer->removeUpgrade(upgrade);
		}
	}
}
